<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Documento extends Model { protected $guarded=[]; protected $casts=['fecha'=>'date','registrado_at'=>'datetime','anulado_at'=>'datetime']; public function tipo(){return $this->belongsTo(TipoDocumento::class,'tipo_documento_id');} public function detalles(){return $this->hasMany(DocumentoDetalle::class);} public function movimientosInventario(){return $this->hasMany(MovimientoInventario::class);} public function tercero(){return $this->belongsTo(Tercero::class);} public function bodega(){return $this->belongsTo(Bodega::class);} public function usuario(){return $this->belongsTo(User::class,'user_id');} public function comprobantesContables(){return $this->hasMany(ComprobanteContable::class);} }
